#!/usr/bin/env python3
from pathlib import Path
from datetime import datetime
import sys
p=Path('index.html')
if not p.is_file():sys.exit('STOP: Run in the Touchline-legend directory; index.html not found.')
s=p.read_text(encoding='utf-8')
if 'id="tlScoutingDedicatedScreen"' in s:sys.exit('STOP: Dedicated scouting screen already installed. No changes made.')
if s.count('id="tlScoutingCentreFeature"')!=1 or s.count('</body>')!=1:sys.exit('STOP: Expected scouting feature or closing body not found exactly once. No changes made.')
addition='<style id="tlScoutDedicatedStyle">\n#tlScoutScreen{display:none;background:#06152a}\n#tlScoutScreen .tl-sc-art{position:relative;width:min(100vw,177.78dvh);aspect-ratio:16/9;container-type:inline-size;color:white;background:linear-gradient(110deg,#091a3bca,#07132bdf),url(\'assets/manager-dashboard.png\') center/100% 100% no-repeat;font-family:Arial,sans-serif}\n#tlScoutScreen .tl-sc-title{position:absolute;top:3%;left:23%;width:54%;height:12%;border:3px solid #ffce42;border-radius:60px;background:linear-gradient(#2169c8,#071b4d);display:grid;place-items:center;font-size:3.2cqw;font-weight:900;text-shadow:2px 3px #00112b}\n#tlScoutScreen .tl-sc-content{position:absolute;top:18%;left:6%;width:88%;height:68%;display:grid;grid-template-columns:61% 38%;grid-template-rows:25% 73%;gap:2% 1%;font-size:1.38cqw}\n#tlScoutScreen .tl-sc-card{border:3px solid #ffce42;border-radius:16px;background:linear-gradient(#16488e,#061b47);padding:2%;min-height:0;overflow:hidden}\n#tlScoutScreen .tl-sc-card h2{font-size:1.7cqw;color:#ffdf79;margin:0 0 1.5%;text-align:center}\n#tlScoutScreen .tl-sc-summary{grid-column:1;grid-row:1}\n#tlScoutScreen .tl-sc-report{grid-column:1;grid-row:2}\n#tlScoutScreen .tl-sc-hiring{grid-column:2;grid-row:1 / span 2;overflow:auto}\n#tlScoutScreen .tl-sc-line{padding:1.1% 1.8%;margin:1% 0;border-radius:9px;background:#24539a;line-height:1.3}\n#tlScoutScreen .tl-sc-report .tl-sc-player{font-size:1.8cqw;line-height:1.5;padding:2%;background:#24539a;border-radius:12px;margin:2% 0}\n#tlScoutScreen .tl-sc-actions{display:flex;gap:2%;margin-top:2%}\n#tlScoutScreen .ex-button{border:2px solid #ffce42;border-radius:12px;background:linear-gradient(#2670d0,#07265f);color:white;font-weight:900;font-size:1.3cqw;cursor:pointer;padding:1.4% 3%}\n#tlScoutScreen .tl-scout-option{display:flex;align-items:center;justify-content:space-between;gap:2%;border-bottom:1px solid #ffffff33;padding:2% 0;font-size:1.16cqw}\n#tlScoutScreen .tl-scout-option .ex-button{flex-shrink:0;font-size:1.1cqw}\n#tlScoutScreen .tl-sc-footer{position:absolute;bottom:2%;left:6%;width:88%;height:9%;display:flex;gap:2%}\n#tlScoutScreen .tl-sc-footer button{flex:1;border:3px solid #ffce42;border-radius:16px;background:linear-gradient(#2670d0,#07265f);color:white;font-size:1.8cqw;font-weight:900;cursor:pointer}\n</style>\n<section id="tlScoutScreen" class="screen"><div class="tl-sc-art"><div class="tl-sc-title">SCOUTING CENTRE</div><div class="tl-sc-content"><div class="tl-sc-card tl-sc-summary"><h2>YOUR SCOUT &amp; WAGE BUDGET</h2><div id="tlScSummary"></div></div><div class="tl-sc-card tl-sc-report"><h2>LATEST PLAYER REPORT</h2><div id="tlScReport"></div></div><div class="tl-sc-card tl-sc-hiring"><h2>HIRE OR REPLACE SCOUT</h2><div id="tlScHiring"></div></div></div><div class="tl-sc-footer"><button type="button" onclick="openTransfers()">BACK TO TRANSFERS</button><button type="button" onclick="openDashboard()">MISSION CONTROL</button></div></div></section>\n<script id="tlScoutingDedicatedScreen">\n(function(){\n \'use strict\';\n const oldShowFootball=showFootballScreen;\n showFootballScreen=function(id){const sc=document.getElementById(\'tlScoutScreen\');if(sc)sc.style.display=\'none\';return oldShowFootball(id);};\n const oldOpenDashboard=openDashboard;\n openDashboard=function(){document.getElementById(\'tlScoutScreen\').style.display=\'none\';return oldOpenDashboard();};\n const oldOpenTransfers=openTransfers;\n openTransfers=function(){oldOpenTransfers();const tab=document.getElementById(\'tlScoutTab\');if(tab){tab.onclick=openScouting;tab.textContent=\'SCOUTING CENTRE\';}};\n window.openScouting=function(){\n  oldOpenTransfers();\n  document.getElementById(\'transfersScreen\').style.display=\'none\';\n  document.getElementById(\'tlScoutScreen\').style.display=\'flex\';\n  transferTab=\'scouting\';renderTransfers();\n };\n const oldRender=renderTransfers;\n renderTransfers=function(){\n  if(transferTab!==\'scouting\')return oldRender();\n  oldRender();\n  const panel=document.getElementById(\'tlScoutPanel\');if(!panel)return;\n  const summary=document.getElementById(\'tlScSummary\'),report=document.getElementById(\'tlScReport\'),hiring=document.getElementById(\'tlScHiring\');\n  summary.replaceChildren();report.replaceChildren();hiring.replaceChildren();\n  let actions=null;\n  Array.from(panel.children).forEach(node=>{\n   const t=node.textContent||\'\';\n   if(node.classList.contains(\'tl-scout-option\')){hiring.appendChild(node);return;}\n   if(t.startsWith(\'HIRE OR REPLACE\'))return;\n   if(t.startsWith(\'SHARED WEEKLY WAGES\')||t.startsWith(\'EMPLOYED:\')||t.startsWith(\'NO SCOUT EMPLOYED\')||t.startsWith(\'NEXT REPORT:\')||t.startsWith(\'NEW PLAYER REPORT AVAILABLE\')){\n    node.className=\'tl-sc-line\';summary.appendChild(node);return;\n   }\n   if(t.startsWith(\'DISCOVERED PLAYER:\')){\n    node.className=\'tl-sc-player\';\n    const p=t.replace(\'DISCOVERED PLAYER: \',\'\').split(\' · \');\n    node.replaceChildren();\n    p.forEach((part,i)=>{const div=document.createElement(\'div\');div.textContent=part;if(i===0){const b=document.createElement(\'strong\');b.textContent=part;div.replaceChildren(b);}node.appendChild(div);});\n    report.appendChild(node);return;\n   }\n   if(node.tagName===\'BUTTON\'){\n    if(t===\'SIGN PLAYER\'||t===\'DISMISS REPORT\'){if(!actions){actions=document.createElement(\'div\');actions.className=\'tl-sc-actions\';report.appendChild(actions);}actions.appendChild(node);}\n    else hiring.appendChild(node);\n   }else report.appendChild(node);\n  });\n  if(!report.children.length){const p=document.createElement(\'div\');p.className=\'tl-sc-line\';p.textContent=\'No player report available yet. Your scout discovers a new player every four completed league matchweeks.\';report.appendChild(p);}\n  const active=document.getElementById(\'tlScoutScreen\').style.display===\'flex\';\n  if(active)document.getElementById(\'transfersScreen\').style.display=\'none\';\n };\n})();\n</script>'
backup=p.with_name('index-backup-before-scout-screen-'+datetime.now().strftime('%Y%m%d-%H%M%S')+'.html')
backup.write_text(s,encoding='utf-8')
new=s.replace('</body>',addition+'\n</body>')
p.write_text(new,encoding='utf-8')
print('Backup:',backup)
print('Dedicated scouting screen installed. Existing scouting calculations unchanged.')
print('Check:',new.count('id="tlScoutingDedicatedScreen"'),'dedicated screen script.')
